-- Standalone fixture. Only run in a new disposable database.
\set ON_ERROR_STOP on
CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$SELECT (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid$$;
GRANT USAGE ON SCHEMA auth TO authenticated;
CREATE TABLE auth.users(id uuid PRIMARY KEY,created_at timestamptz DEFAULT now(),raw_user_meta_data jsonb DEFAULT '{}');
\ir ../../supabase/migrations/20261107_announcements.sql
CREATE FUNCTION pg_temp.check(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL %',label; END IF; RAISE NOTICE 'PASS %',label; END $$;
INSERT INTO auth.users(id) SELECT ('00000000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid FROM generate_series(1,8) i;
SELECT pg_temp.check(public.findez_claim_announcement('00000000-0000-0000-0000-000000000001',gen_random_uuid(),'ios',1,true) IS NULL,'drafts never deliver');
UPDATE public.announcement_campaigns SET status='published';
SELECT pg_temp.check(public.findez_claim_announcement('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','ios',1,true)->>'id'='founders-access-v1','welcome priority');
SELECT pg_temp.check(public.findez_claim_announcement('00000000-0000-0000-0000-000000000001',gen_random_uuid(),'ios',1,true) IS NULL,'other device suppressed after claim');
SELECT pg_temp.check(NOT public.findez_announcement_receipt('00000000-0000-0000-0000-000000000002','founders-access-v1','dismissed'),'cannot dismiss another user claim');
SELECT pg_temp.check(public.findez_announcement_receipt('00000000-0000-0000-0000-000000000001','founders-access-v1','acknowledged'),'acknowledge owned claim');
SELECT public.findez_announcement_receipt('00000000-0000-0000-0000-000000000001','founders-access-v1','acknowledged');
SELECT pg_temp.check((SELECT count(*)=1 AND min(acknowledged_at)=min(dismissed_at) FROM public.user_announcement_state),'idempotent receipt');
UPDATE public.user_announcement_state SET claimed_at=now()-interval '8 days';
SELECT pg_temp.check(public.findez_claim_announcement('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','ios',1,true) IS NULL,'same session never stacks even beyond cap');
SELECT pg_temp.check(public.findez_claim_announcement('00000000-0000-0000-0000-000000000001',gen_random_uuid(),'ios',1,true)->>'category'='product_update','queued update after cap');
SELECT pg_temp.check(public.findez_claim_announcement('00000000-0000-0000-0000-000000000002',gen_random_uuid(),'android',1,true) IS NULL,'platform targeting');
UPDATE public.announcement_campaigns SET min_client=2;
SELECT pg_temp.check(public.findez_claim_announcement('00000000-0000-0000-0000-000000000002',gen_random_uuid(),'ios',1,true) IS NULL,'client capability targeting');
UPDATE public.announcement_campaigns SET min_client=1, starts_at=now()+interval '1 day';
SELECT pg_temp.check(public.findez_claim_announcement('00000000-0000-0000-0000-000000000002',gen_random_uuid(),'ios',1,true) IS NULL,'future scheduling');
UPDATE public.announcement_campaigns SET starts_at=now()-interval '3 days',expires_at=now()-interval '1 day';
SELECT pg_temp.check(public.findez_claim_announcement('00000000-0000-0000-0000-000000000002',gen_random_uuid(),'ios',1,true) IS NULL,'expired campaigns');
UPDATE public.announcement_campaigns SET expires_at=NULL,rollout_percent=0;
SELECT pg_temp.check(public.findez_claim_announcement('00000000-0000-0000-0000-000000000002',gen_random_uuid(),'ios',1,true) IS NULL,'zero rollout');
UPDATE public.announcement_campaigns SET rollout_percent=100,audience='existing',audience_cutoff=now()-interval '1 day';
SELECT pg_temp.check(public.findez_claim_announcement('00000000-0000-0000-0000-000000000002',gen_random_uuid(),'ios',1,true) IS NULL,'existing audience excludes new users');
UPDATE public.announcement_campaigns SET audience='all';
UPDATE auth.users SET raw_user_meta_data='{"findez_plan_intro_version":1}' WHERE id='00000000-0000-0000-0000-000000000002';
SELECT pg_temp.check(public.findez_claim_announcement('00000000-0000-0000-0000-000000000002',gen_random_uuid(),'ios',1,true)->>'id'<>'founders-access-v1','legacy server welcome suppressed');
SELECT pg_temp.check(public.findez_claim_announcement('00000000-0000-0000-0000-000000000003',gen_random_uuid(),'ios',1,true,true)->>'id'<>'founders-access-v1','legacy local welcome suppressed');
SELECT pg_temp.check(public.findez_claim_announcement('00000000-0000-0000-0000-000000000004',gen_random_uuid(),'ios',1,false)->>'id'='auto-extract-v1','pilot campaign does not mislabel paid user');
UPDATE public.announcement_campaigns SET status='archived';
INSERT INTO public.announcement_campaigns(id,category,design,status,title) VALUES('milestone-test','founders','message','published','Test milestone'),('milestone-next-test','founders','message','published','Test milestone next');
SELECT public.findez_claim_announcement('00000000-0000-0000-0000-000000000005',gen_random_uuid(),'ios',1,true);
UPDATE public.user_announcement_state SET claimed_at=now()-interval '8 days' WHERE user_id='00000000-0000-0000-0000-000000000005';
SELECT pg_temp.check(public.findez_claim_announcement('00000000-0000-0000-0000-000000000005',gen_random_uuid(),'ios',1,true) IS NULL,'founders thirty day cap');
UPDATE public.user_announcement_state SET claimed_at=now()-interval '31 days' WHERE user_id='00000000-0000-0000-0000-000000000005';
SELECT pg_temp.check(public.findez_claim_announcement('00000000-0000-0000-0000-000000000005',gen_random_uuid(),'ios',1,true) IS NOT NULL,'founders next genuine campaign after thirty days');
SELECT pg_temp.check(NOT has_function_privilege('authenticated','public.findez_claim_announcement(uuid,uuid,text,integer,boolean,boolean)','execute'),'clients cannot claim directly');
SELECT pg_temp.check(NOT has_table_privilege('authenticated','public.announcement_campaigns','select'),'drafts and targeting private');
SELECT pg_temp.check(NOT has_table_privilege('authenticated','public.user_announcement_state','update'),'clients cannot forge delivery times');
SET ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001"}',false);
SELECT pg_temp.check((SELECT bool_and(user_id='00000000-0000-0000-0000-000000000001') FROM public.user_announcement_state),'RLS own state only');
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","api_key_id":"test"}',false);
SELECT pg_temp.check((SELECT count(*)=0 FROM public.user_announcement_state),'integration keys cannot read personal receipts');
RESET ROLE;
